import React from 'react';
import { useNavigate } from 'react-router-dom'; // إضافة المكتبة للتنقل بين الصفحات
import { Building2, MapPin, Search } from 'lucide-react';

const StudentOffers = () => {
  const navigate = useNavigate(); // تعريف دالة التنقل

  const offers = [
    { id: 1, title: "مطور ويب React", company: "Tech Solutions", location: "قسنطينة" },
    { id: 2, title: "مصمم واجهات UI/UX", company: "Creative DZ", location: "سطيف" }
  ];

  // دالة التعامل مع الضغط على الزر
  const handleViewDetails = (id) => {
    // توجيه المستخدم إلى رابط التفاصيل الخاص بالعرض
    navigate(`/student/offer/${id}`);
  };

  return (
    <div className="p-8 text-right" dir="rtl">
      <div className="relative mb-8">
        <input 
          type="text" 
          placeholder="ابحث عن تربص..." 
          className="w-full p-4 pr-12 rounded-2xl bg-white border-none shadow-sm focus:ring-2 focus:ring-blue-600 outline-none" 
        />
        <Search className="absolute right-4 top-4 text-slate-400" />
      </div>

      <div className="grid md:grid-cols-2 gap-6">
        {offers.map(offer => (
          <div key={offer.id} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 hover:shadow-md transition-shadow">
            <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-xl mb-4 flex items-center justify-center">
              <Building2/>
            </div>
            <h3 className="font-bold text-lg">{offer.title}</h3>
            <p className="text-slate-500 text-sm mb-4">{offer.company}</p>
            <div className="flex items-center gap-2 text-slate-400 text-xs mb-6">
              <MapPin size={14}/> {offer.location}
            </div>
            
            {/* إضافة حدث onClick هنا */}
            <button 
              onClick={() => handleViewDetails(offer.id)}
              className="w-full py-3 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-colors"
            >
              عرض التفاصيل
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default StudentOffers;
